        sizes[i] = resolvePerParticle(size, i, DEFAULT_SIZE$1);
        tmpColor.set(resolvePerParticle(color, i, DEFAULT_COLOR));
        colors[i * 3] = tmpColor.r;
        colors[i * 3 + 1] = tmpColor.g;
        colors[i * 3 + 2] = tmpColor.b;
