        this.#cpuPosition[slot * 3 + 2] = positions[i * 3 + 2];
        this.#cpuVelocity[slot * 3] = velocities[i * 3];
        this.#cpuVelocity[slot * 3 + 1] = velocities[i * 3 + 1];
        this.#cpuVelocity[slot * 3 + 2] = velocities[i * 3 + 2];
        this.#cpuAge[slot] = 0;
        this.#cpuLifetime[slot] = lifetimes[i];
